<script>
(()=>{const root=document.querySelector('.dsc[data-status-url]');if(!root)return;const url=root.dataset.statusUrl,badge=document.getElementById('support-deposit-status'),value=document.getElementById('support-status-value'),received=document.getElementById('support-received'),ngn=document.getElementById('support-ngn'),sync=document.getElementById('support-sync'),note=document.getElementById('support-status-note');let busy=false;const labels={pending:'Awaiting payment',expired:'Payment window ended',awaiting_admin_review:'Confirmed · awaiting review',completed:'Completed · wallet credited',failed:'Needs attention'};async function refresh(){if(busy||document.visibilityState!=='visible')return;busy=true;try{const r=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw new Error();const d=await r.json(),text=labels[d.status]||'Processing';badge.textContent=text;value.textContent=text;badge.classList.toggle('done',d.wallet_credited||d.status==='completed');badge.classList.toggle('bad',d.status==='failed'||d.status==='expired');if(Number(d.received_amount)>0)received.textContent=Number(d.received_amount).toFixed(8)+' '+String(d.currency||'').toUpperCase();if(Number(d.ngn_credited_amount)>0)ngn.textContent='₦'+Number(d.ngn_credited_amount).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2});if(d.status==='completed')note.innerHTML='<i class="bi bi-check-circle me-1"></i>This deposit has a recorded wallet credit. Tell us if the amount or balance does not match your expectation.';else if(d.status==='awaiting_admin_review')note.innerHTML='<i class="bi bi-info-circle me-1"></i>The transfer is confirmed and waiting for a KayXchange review before settlement.';sync.textContent='Live status · checked '+new Date().toLocaleTimeString()}catch(_){sync.textContent='Status service is temporarily unavailable · retrying'}finally{busy=false}}refresh();setInterval(refresh,15000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()});window.addEventListener('focus',refresh)})();
</script>
